let ALL_ITEMS_CACHE = null;     // full Add_Item_Report catalog, loaded once and cached
let ALL_ITEMS_LOADING = null;   // in-flight loading promise (avoids duplicate fetches)

async function ensureAllItemsLoaded() {
  if (ALL_ITEMS_CACHE) return ALL_ITEMS_CACHE;
  if (ALL_ITEMS_LOADING) return ALL_ITEMS_LOADING;

  ALL_ITEMS_LOADING = (async () => {
    let items;
    try {
      items = await fetchAllRecords("Add_Item_Report", {
        field_config: "custom",
        fields: ITEM_FIELDS
      });
    } catch (err) {
      console.warn("Custom-field full item load failed, retrying with all fields:", err);
      try {
        items = await fetchAllRecords("Add_Item_Report", { field_config: "all" });
      } catch (err2) {
        console.error("Failed to load full item catalog:", err2);
        items = [];
      }
    }
    ALL_ITEMS_CACHE = items;
    ALL_ITEMS_LOADING = null;
    return items;
  })();

  return ALL_ITEMS_LOADING;
}

// Reorders a claim's effective lines so rows with the same item number
// sit next to each other (needed for rowspan grouping), while preserving
// each individual Date of Service row and first-seen item order.
function getGroupedByItemLines(c) {
  const lines = getEffectiveClaimLines(c);
  const groups = new Map();
  const order = [];

  lines.forEach(l => {
    const itemNo = getLineItemNumber(l);
    if (!groups.has(itemNo)) {
      groups.set(itemNo, []);
      order.push(itemNo);
    }
    groups.get(itemNo).push(l);
  });

  const result = [];
  order.forEach(itemNo => groups.get(itemNo).forEach(l => result.push(l)));
  return result;
}


