// "MARIA ANITA FERRER - 29 Sept 1962"  ->  "MARIA ANITA FERRER"
// "MARIA ANITA FERRER - 29 Sept 1962"  ->  "MARIA ANITA FERRER"
function stripDob(text) {
  const D = "(?:\\d{1,2}\\s+[A-Za-z]+\\.?,?\\s+\\d{4}|\\d{1,2}[\\/.-]\\d{1,2}[\\/.-]\\d{2,4}|\\d{4}-\\d{2}-\\d{2})";
  const re = new RegExp("\\s*(?:[-â€“,]\\s+|\\(\\s*)(?:DOB:?\\s*)?" + D + "\\s*\\)?\\s*$", "i");
  return String(text || "").replace(re, "").trim();
}

// true when a line is only a date, e.g. "29 Sept 1962" or "29/09/1962"
function isDateOnly(text) {
  return /^\s*(?:DOB:?\s*)?(?:\d{1,2}\s+[A-Za-z]+\.?,?\s+\d{4}|\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}|\d{4}-\d{2}-\d{2})\s*$/i
    .test(String(text || ""));
}
function toLabel(v) {
  if (v === null || v === undefined || v === "") return "";
  if (Array.isArray(v)) return v.map(toLabel).filter(Boolean).join(", ");
  if (typeof v === "object") return v.zc_display_value || v.display_value || v.ID || "";
  return String(v);
}

// "1234 - Some description" -> "1234"
function normItemKey(v) {
  return String(v || "").split(/\s[-â€“]\s/)[0].trim().toLowerCase();
}
function parseZohoDate(dateStr) {
  if (!dateStr) return null;
  if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;
  const str = String(dateStr).trim();
  if (!str) return null;

  // Handle DD/MM/YYYY or DD-MM-YYYY (Australian standard format)
  const dmyMatch = str.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (dmyMatch) {
    const day = parseInt(dmyMatch[1], 10);
    const month = parseInt(dmyMatch[2], 10) - 1;
    const year = parseInt(dmyMatch[3], 10);
    const d = new Date(year, month, day);
    return isNaN(d.getTime()) ? null : d;
  }

  // Handle YYYY-MM-DD (ISO format from HTML date inputs)
  const ymdMatch = str.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);
  if (ymdMatch) {
    const year = parseInt(ymdMatch[1], 10);
    const month = parseInt(ymdMatch[2], 10) - 1;
    const day = parseInt(ymdMatch[3], 10);
    const d = new Date(year, month, day);
    return isNaN(d.getTime()) ? null : d;
  }

  // Handle "28 Sept 2026" or "28-Sept-2026" -> normalize "Sept" to "Sep"
  const clean = str.replace(/-/g, " ").replace(/\bSept\b/gi, "Sep");
  const d = new Date(clean);
  if (!isNaN(d.getTime())) {
    return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }
  return null;
}

function showLoading() {
  const el = document.getElementById("fxLoader");
  if (!el) return;
  setLoadingProgress(5, "Initializing secure connection");
  el.classList.add("is-active"); // â¬…ï¸ harmless now (already active from HTML), but kept as a safety net in case the overlay was ever hidden/removed programmatically elsewhere
}

function setLoadingProgress(pct, text) {
  const fill = document.getElementById("fxBarFill");
  const pctEl = document.getElementById("fxPct");
  const status = document.getElementById("fxStatus");
  if (fill)  fill.style.width = pct + "%";
  if (pctEl) pctEl.textContent = Math.round(pct) + "%";
  if (status && text) status.textContent = text;
}

function hideLoading() {
  const el = document.getElementById("fxLoader");
  if (!el) return;
  setLoadingProgress(100, "Ready");
  setTimeout(() => el.classList.remove("is-active"), 400);
}

document.addEventListener("DOMContentLoaded", async function () {

  showLoading();
  initSearchableSelect("f-location", "All Hospitals");
  initSearchableSelect("f-patient",  "All Patients");
  initSearchableSelect("f-payer",    "All Payers");

  try {
    if (typeof ZOHO === "undefined") {
      console.error("ZOHO SDK not loaded");
      return;
    }

    console.time("total load");

    /* 0) Get Logged-in User Email */
    let initParams = null;
    try {
      if (window.ZOHO?.CREATOR?.UTIL && typeof ZOHO.CREATOR.UTIL.getInitParams === "function") {
        initParams = await ZOHO.CREATOR.UTIL.getInitParams();
        CURRENT_USER_EMAIL = (initParams && initParams.loginUser) ? String(initParams.loginUser).trim() : "";
        console.log("Logged in user email:", CURRENT_USER_EMAIL);
      }
    } catch (paramErr) {
      console.warn("Could not retrieve initParams / loginUser:", paramErr);
    }

    if (!CURRENT_USER_EMAIL) {
      const urlParams = new URLSearchParams(window.location.search);
      CURRENT_USER_EMAIL = (urlParams.get("loginUser") || urlParams.get("user") || urlParams.get("email") || "").trim();
    }

    setLoadingProgress(15, "Identifying doctor profile");

    /* 1) Fetch doctors & mappings to identify current doctor */
    // Primary report requested: #Report:Portal_Doctors1, with fallback to Doctors1 and All_Doctors
    const [allDoctors, allHospitals, allMappings] = await Promise.all([
      fetchRecordsWithFallback("Portal_Doctors1", "Doctors1", "All_Doctors"),
      fetchAllRecords("All_Hospitals"),
      fetchRecordsWithFallback("Doctor_Hospital_Mappings", "All_Doctor_Hospital_Mappings1")
    ]);

    // Match doctor by loginUser email: login user id = #Report:Portal_Doctors1 Email
    let myDoctor = null;
    if (CURRENT_USER_EMAIL) {
      const emailLower = CURRENT_USER_EMAIL.toLowerCase();
      myDoctor = allDoctors.find(d => {
        const docEmail = getDoctorEmail(d);
        if (docEmail && docEmail === emailLower) return true;
        if (d.ID && String(d.ID).trim() === CURRENT_USER_EMAIL) return true;
        return false;
      });
    }

    if (myDoctor) {
      CURRENT_DOCTOR_ID = myDoctor.ID;
      CURRENT_DOCTOR_NAME = myDoctor.Doctor_Name
        || myDoctor.Name?.zc_display_value
        || (myDoctor.Name && (myDoctor.Name.first_name || myDoctor.Name.last_name)
            ? `${myDoctor.Name.prefix || ""} ${myDoctor.Name.first_name || ""} ${myDoctor.Name.last_name || ""}`.trim()
            : "")
        || myDoctor.zc_display_value
        || CURRENT_USER_EMAIL;
    } else {
      CURRENT_DOCTOR_ID = null;
      CURRENT_DOCTOR_NAME = null;
    }

    const doctorDisplayEl = document.getElementById("f-doctor-display");
    if (doctorDisplayEl) {
      if (CURRENT_DOCTOR_NAME) {
        doctorDisplayEl.textContent = CURRENT_DOCTOR_NAME;
        doctorDisplayEl.title = `Logged in: ${CURRENT_DOCTOR_NAME} (${CURRENT_USER_EMAIL})`;
      } else if (CURRENT_USER_EMAIL) {
        doctorDisplayEl.textContent = "Doctor profile not found";
        doctorDisplayEl.title = `No doctor matched for email: ${CURRENT_USER_EMAIL}`;
      } else {
        doctorDisplayEl.textContent = "—";
      }
    }

    setLoadingProgress(35, "Fetching claims for doctor");

    /* 2) Fetch claims: #Report:Add_Claim_Report (fallback Doctors_Claim_Report) */
    const allClaims = await fetchRecordsWithFallback("Add_Claim_Report", "Doctors_Claim_Report");

    // Filter claims: #Report:Portal_Doctors1 = #Report:Add_Claim_Report Doctor
    let claims = allClaims;
    if (CURRENT_DOCTOR_ID || CURRENT_DOCTOR_NAME) {
      claims = allClaims.filter(c => isClaimForDoctor(c, CURRENT_DOCTOR_ID, CURRENT_DOCTOR_NAME));
    } else if (CURRENT_USER_EMAIL) {
      // Portal user logged in but no doctor profile matched: show no claims
      claims = [];
    }
    ALL_CLAIMS = claims;
    FILTERED_DATA = claims;

    /* 3) Build doctor-hospital mappings & set allowed hospitals */
    buildDoctorHospitalMap(allMappings);

    if (CURRENT_DOCTOR_ID || CURRENT_DOCTOR_NAME) {
      let docHospitals = (CURRENT_DOCTOR_ID && DOCTOR_HOSPITAL_MAP[String(CURRENT_DOCTOR_ID)])
        ? DOCTOR_HOSPITAL_MAP[String(CURRENT_DOCTOR_ID)]
        : [];

      if (docHospitals.length === 0 && CURRENT_DOCTOR_NAME && DOCTOR_HOSPITAL_MAP[CURRENT_DOCTOR_NAME.trim().toLowerCase()]) {
        docHospitals = DOCTOR_HOSPITAL_MAP[CURRENT_DOCTOR_NAME.trim().toLowerCase()];
      }

      // If no hospital mappings found, extract active hospitals directly from doctor's claims
      if (docHospitals.length === 0) {
        const seenH = new Set();
        const extracted = [];
        (ALL_CLAIMS || []).forEach(c => {
          const hid = getLookupId(c.Hospital) || c.Hospital_ID;
          const hlabel = getLookupLabel(c.Hospital) || c.Hospital_Name;
          if (hid && !seenH.has(String(hid))) {
            seenH.add(String(hid));
            extracted.push({ value: String(hid), label: hlabel || "Hospital" });
          }
        });
        docHospitals = extracted;
      }

      ALLOWED_HOSPITALS = docHospitals;
      ALL_HOSPITALS = ALLOWED_HOSPITALS;
    } else {
      ALL_HOSPITALS = allHospitals.map(hos => ({
        value: String(hos.ID),
        label: hos.Hospital_Name || hos.zc_display_value
      }));
    }
    populateHospitals(ALL_HOSPITALS);

    setLoadingProgress(55, "Loading patients and items");

    /* 4) Fetch patients & items in parallel */
    const [items, patients] = await Promise.all([
      fetchItemsForClaims(claims),
      fetchRecordsWithFallback("My_Patients", "Add_Patient_Report"),
      loadInitialItemNumbers()   // seeds the Item Number filter with 200 records only
    ]);
    setLoadingProgress(75, "Building lookup maps");

    /* 5) Lookup maps (before rendering) */
    buildItemTypeMap(items);
    buildPatientPayerMap(patients);
    buildPatientInfoMap(patients);
    setLoadingProgress(90, "Rendering report");

    /* 6) Filters + table: strictly doctor-scoped */
    populatePayers(claims);
    populatePatients(patients, claims);

    // Apply initial Fully Paid filter
    FILTERED_DATA = ALL_CLAIMS.filter(c => {
      const s = String(c.Status?.zc_display_value || c.Status || "").trim().toLowerCase();
      return s === "fully paid";
    });
    renderTable(FILTERED_DATA);

    console.timeEnd("total load");

  } catch (error) {
    console.error("Error:", error);
  } finally {
    hideLoading();
  }
});


/* ===================================================
   ITEM NUMBER FILTER (multiselect)
   =================================================== */

// Fetch just the first 200 items to seed the dropdown quickly
async function loadInitialItemNumbers() {
  try {
    const resp = await ZOHO.CREATOR.DATA.getRecords({
      report_name: "Add_Item_Report",
      field_config: "custom",
      fields: ITEM_FIELDS,   // "Item,Type_field,Description"
      max_records: 200
    });
    setItemNumberOptions(resp.data || []);
  } catch (err) {
    console.warn("Custom-field initial item load failed, retrying with all fields:", err);
    try {
      const resp = await ZOHO.CREATOR.DATA.getRecords({
        report_name: "Add_Item_Report",
        field_config: "all",
        max_records: 200
      });
      setItemNumberOptions(resp.data || []);
    } catch (err2) {
      console.error("Failed to load initial item numbers entirely:", err2);
    }
  }
}

// Called on search input (debounced) to query the server for matches
// Called on search input (debounced) to query the server for matches
async function searchItemNumbersRemote(query) {
  const wrapper = document.getElementById("f-itemnumber");
  const loader  = wrapper?.querySelector(".ms-loading");
  const list    = wrapper?.querySelector(".ms-options");
  const seq = ++ITEM_SEARCH_SEQ; // guards against out-of-order responses

  loader?.classList.add("active");

  try {
    const items = await ensureAllItemsLoaded();
    if (seq !== ITEM_SEARCH_SEQ) return; // a newer keystroke already fired

    const q = query.trim().toLowerCase();
    const filtered = q
      ? items.filter(it => {
          const num  = toLabel(it[ITEM_NUMBER_FIELD] ?? it.Item ?? it.zc_display_value);
          const type = toLabel(it.Type_field);
          const desc = toLabel(it.Description);
          return `${num} ${type} ${desc}`.toLowerCase().includes(q);
        })
      : items.slice(0, 200); // show first 200 until user types

    setItemNumberOptions(filtered); // rebuilds the checkbox list from Add_Item_Report data
  } catch (err) {
    console.error("Item number search failed:", err);
  } finally {
    if (seq === ITEM_SEARCH_SEQ) loader?.classList.remove("active");
  }
}

// Builds the dropdown list from whatever batch of item records we have,
// also caching Type/Description so table rendering still resolves correctly.
function setItemNumberOptions(items) {
  const seen = new Set();
  const list = [];
  items.forEach(it => {
    const rawNum = it[RESOLVED_ITEM_FIELD || ITEM_NUMBER_FIELD] ?? it.Item ?? it.zc_display_value;
    const num = toLabel(rawNum);
    if (!num || seen.has(num)) return;
    seen.add(num);

    const type = toLabel(it.Type_field) || "-";
    const desc = toLabel(it.Description) || "-";
    const key  = "num:" + normItemKey(num);
    if (!ITEM_TYPE_MAP[key]) ITEM_TYPE_MAP[key] = type;
    if (!ITEM_DESC_MAP[key]) ITEM_DESC_MAP[key] = desc;

    const label = type !== "-" ? `${num} - ${type}` : num;
    ITEM_OPTION_CACHE.set(num, label);
    list.push({ value: num, label });
  });

  // Keep any currently-checked items visible even if they don't match
  // the current search text, so they can actually be unchecked.
  CHECKED_ITEM_NUMBERS.forEach(val => {
    if (!seen.has(val)) {
      seen.add(val);
      list.push({ value: val, label: ITEM_OPTION_CACHE.get(val) || val });
    }
  });

  list.sort((a, b) => a.label.localeCompare(b.label, undefined, { numeric: true }));
  setMultiSelectOptions("f-itemnumber", list);
}
// Returns a claim's line items, filtered down to only the selected
// item numbers when the Item Number filter is active.
// Add trimming for safety against stray whitespace/formatting mismatches
function getEffectiveClaimLines(c) {
  const lines = getClaimLines(c);            // â† was getClaimUniqueLines(c)
  if (!SELECTED_ITEM_NUMBERS.length) return lines;
  const selected = SELECTED_ITEM_NUMBERS.map(v => String(v).trim());
  return lines.filter(l => selected.includes(String(getLineItemNumber(l)).trim()));
}

