function initMultiSelect(id, allLabel) {
  const wrapper = document.getElementById(id);
  if (!wrapper) {
    console.error(`âŒ Multi-select container not found: #${id}`);
    return;
  }

  wrapper.classList.add("multi-select");
  wrapper.dataset.allLabel = allLabel;

wrapper.innerHTML = `
  <div class="ms-control" tabindex="0">
    <span class="ms-value">${allLabel}</span>
    <span class="ms-count-badge" style="display:none;"></span>
    <span class="ms-arrow">&#9662;</span>
  </div>
  <div class="ms-dropdown">
    <input type="text" class="ms-search" placeholder="Search..." autocomplete="off" />
    <div class="ms-loading"><span class="ms-spinner"></span><span>Searching...</span></div>
    <ul class="ms-options"></ul>
    <div class="ms-actions">
      <button type="button" class="ms-clear">Clear all</button>
      <button type="button" class="ms-apply">Done</button>
    </div>
  </div>
`;

  const control  = wrapper.querySelector(".ms-control");
  const dropdown = wrapper.querySelector(".ms-dropdown");
  const search   = wrapper.querySelector(".ms-search");
  const clearBtn = wrapper.querySelector(".ms-clear");
  const applyBtn = wrapper.querySelector(".ms-apply");

  // Toggle open/closed only from the control itself
  control.addEventListener("click", (e) => {
    e.stopPropagation();
    const willOpen = !wrapper.classList.contains("open");
    closeAllSearchableSelects();
    closeAllMultiSelects();
    if (willOpen) {
      wrapper.classList.add("open");
      search.value = "";
      filterMultiOptions(wrapper, "");
      setTimeout(() => search.focus(), 0);
    }
  });

  // ðŸ”‘ THE FIX: stop every click inside the dropdown panel
  // (search box, checkbox list, labels, checkboxes, buttons)
  // from bubbling up to the document-level "close all" listener.
  dropdown.addEventListener("click", (e) => e.stopPropagation());
  dropdown.addEventListener("mousedown", (e) => e.stopPropagation());

  search.addEventListener("input", () => {
  filterMultiOptions(wrapper, search.value); // instant filter on currently loaded batch
  if (id === "f-itemnumber") {
    clearTimeout(ITEM_SEARCH_TIMER);
    ITEM_SEARCH_TIMER = setTimeout(() => searchItemNumbersRemote(search.value), 350);
  }
});
  search.addEventListener("keydown",(e) => {
    if (e.key === "Escape") wrapper.classList.remove("open");
  });

clearBtn.addEventListener("click", () => {
  wrapper.querySelectorAll('.ms-option input[type="checkbox"]').forEach(cb => cb.checked = false);
  if (id === "f-itemnumber") CHECKED_ITEM_NUMBERS.clear();
  updateMultiSelectLabel(wrapper, allLabel);
  reorderMultiSelectChecked(wrapper); // â¬…ï¸ ADDED â€” restore natural order after clearing
});

  applyBtn.addEventListener("click", () => {
    wrapper.classList.remove("open");
  });
}

// Reorders the option <li>s so checked items appear first, keeping the
// natural (alphabetical) order within each group. Used for Patient & Item Number.
function reorderMultiSelectChecked(wrapper) {
  const list = wrapper.querySelector(".ms-options");
  if (!list) return;
  const noResults = list.querySelector(".ms-no-results");
  const optionsByValue = new Map();
  list.querySelectorAll(".ms-option").forEach(li => {
    const cb = li.querySelector('input[type="checkbox"]');
    if (cb) optionsByValue.set(cb.value, li);
  });

  const order = wrapper._msOriginalOrder || Array.from(optionsByValue.keys());
  const checked = [];
  const unchecked = [];

  order.forEach(val => {
    const li = optionsByValue.get(val);
    if (!li) return;
    const cb = li.querySelector('input[type="checkbox"]');
    (cb && cb.checked ? checked : unchecked).push(li);
  });

  checked.forEach(li => list.appendChild(li));
  unchecked.forEach(li => list.appendChild(li));
  if (noResults) list.appendChild(noResults);
}

function setMultiSelectOptions(id, items) {
  const wrapper = document.getElementById(id);
  if (!wrapper) return;

  const allLabel = wrapper.dataset.allLabel || "All";
  const list = wrapper.querySelector(".ms-options");
  list.innerHTML = "";

  wrapper._msOriginalOrder = items.map(item => String(item.value)); // â¬…ï¸ ADDED â€” remembers natural order for checked-to-top sorting

  items.forEach(item => {
    const li = document.createElement("li");
    li.classList.add("ms-option");
    li.innerHTML = `
      <label>
        <input type="checkbox" value="${item.value}" />
        <span class="ms-checkmark"></span>
        <span class="ms-option-text">${item.label}</span>
      </label>
    `;
    list.appendChild(li);
  });

  const noResultsLi = document.createElement("li");
  noResultsLi.textContent = "No matches found";
  noResultsLi.classList.add("ms-no-results");
  list.appendChild(noResultsLi);

  const isItemNumber = id === "f-itemnumber";

  list.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    if (isItemNumber) cb.checked = CHECKED_ITEM_NUMBERS.has(cb.value);
    cb.addEventListener("change", () => {
      if (isItemNumber) {
        cb.checked ? CHECKED_ITEM_NUMBERS.add(cb.value) : CHECKED_ITEM_NUMBERS.delete(cb.value);
      }
      updateMultiSelectLabel(wrapper, allLabel);
      reorderMultiSelectChecked(wrapper); // â¬…ï¸ ADDED â€” move the item to the top the moment it's checked
    });
  });

  updateMultiSelectLabel(wrapper, allLabel);
  reorderMultiSelectChecked(wrapper); // â¬…ï¸ ADDED â€” keep previously-checked items on top when the list is rebuilt
}

function updateMultiSelectLabel(wrapper, allLabel) {
  const checked = Array.from(wrapper.querySelectorAll('.ms-option input[type="checkbox"]:checked'));
  const valueSpan = wrapper.querySelector(".ms-value");
  if (!checked.length) {
    valueSpan.textContent = allLabel;
  } else if (checked.length === 1) {
    valueSpan.textContent = checked[0].closest("label").querySelector("span").textContent;
  } else {
    valueSpan.textContent = `${checked.length} selected`;
  }
}

function filterMultiOptions(wrapper, query) {
  const q = query.trim().toLowerCase();
  let anyVisible = false;

  wrapper.querySelectorAll(".ms-option").forEach(li => {
    const textSpan = li.querySelector(".ms-option-text"); // â¬…ï¸ FIXED â€” was li.querySelector("span"), which grabbed the empty .ms-checkmark span instead
    if (!textSpan) return;
    const match = textSpan.textContent.toLowerCase().includes(q);
    li.style.display = match ? "" : "none";
    if (match) anyVisible = true;
  });

  const noResults = wrapper.querySelector(".ms-no-results");
  if (noResults) {
    noResults.style.display = (q && !anyVisible) ? "" : "none";
  }
}

function closeAllMultiSelects() {
  document.querySelectorAll(".multi-select.open").forEach(el => {
    el.classList.remove("open");
  });
}

function getMultiSelectValues(id) {
  if (id === "f-itemnumber") return Array.from(CHECKED_ITEM_NUMBERS);
  const wrapper = document.getElementById(id);
  if (!wrapper) return [];
  return Array.from(wrapper.querySelectorAll('.ms-option input[type="checkbox"]:checked')).map(cb => cb.value);
}

