/* ---- Payment Turnaround Days helper (Claim Lodgement Date -> Payment Date) ---- */
function calcPaymentTurnaroundDays(c) {
  const lodgement = parseZohoDate(c.Claim_Date || c.Lodged_Date);
  let payDateRaw = c.Payment_Date || c.payment_date;
  if (!payDateRaw) {
    const lines = getClaimLines(c);
    if (lines.length && lines[0].Payment_Date) payDateRaw = lines[0].Payment_Date;
  }
  const payDate = parseZohoDate(payDateRaw);
  if (!lodgement || !payDate || isNaN(lodgement.getTime()) || isNaN(payDate.getTime())) return null;
  const diff = Math.round((payDate - lodgement) / (1000 * 60 * 60 * 24));
  if (diff < 0) return null;
  return diff;
}

function formatTurnaroundDays(days) {
  if (days === null || days === undefined) return "-";
  return days === 1 ? "1 Day" : `${days} Days`;
}

/* ---- Process Payment Days helper ---- */
function calcProcessPaymentDays(l) {
  const dos = parseZohoDate(l.Date_of_Service);
  const pay = parseZohoDate(l.Payment_Date);
  if (!dos || !pay || isNaN(dos.getTime()) || isNaN(pay.getTime())) return "-";
  const diff = Math.round((pay - dos) / (1000 * 60 * 60 * 24));
  if (diff < 0) return "-";
  return diff === 1 ? "1 Day" : `${diff} Days`;
}

/* ---- Format Claim Date for display ---- */
function formatClaimDate(c) {
  const raw = c.Claim_Date;
  if (!raw) return "-";
  const d = parseZohoDate(raw);
  if (!d || isNaN(d.getTime())) return raw;
  return d.toLocaleDateString("en-AU", { day: "2-digit", month: "2-digit", year: "numeric" });
}

function renderTable(data) {
  const tbody = document.getElementById("report-body");
  tbody.classList.remove("fade-in");
  void tbody.offsetWidth;

  if (!data.length) {
    tbody.innerHTML = `<tr><td colspan="10">No data</td></tr>`;
    renderSummary([]);
    updateAvgTurnaroundBar([]);
    return;
  }

  // Sort by turnaround days if sort is active
  let sortedData = [...data];
  if (TURNAROUND_SORT_DIR === "asc") {
    sortedData.sort((a, b) => {
      const da = calcPaymentTurnaroundDays(a);
      const db = calcPaymentTurnaroundDays(b);
      if (da === null && db === null) return 0;
      if (da === null) return 1;
      if (db === null) return -1;
      return da - db;
    });
  } else if (TURNAROUND_SORT_DIR === "desc") {
    sortedData.sort((a, b) => {
      const da = calcPaymentTurnaroundDays(a);
      const db = calcPaymentTurnaroundDays(b);
      if (da === null && db === null) return 0;
      if (da === null) return 1;
      if (db === null) return -1;
      return db - da;
    });
  }

  let html = "";

  sortedData.forEach((c, groupIdx) => {
    const claimId   = c.Claim_ID || c.ID || "-";
    const claimDate = formatClaimDate(c);
    const doctor    = c.Doctor?.zc_display_value   || c.Doctor_Name   || "-";
    const hospital  = c.Hospital?.zc_display_value || c.Hospital_Name || "-";
    const patientInfo = getClaimPatientInfo(c);
    const patient   = patientInfo ? patientInfo.label : "-";
    const payerObj  = getClaimPayer(c);
    const payer     = payerObj ? payerObj.label : (c.Payer?.zc_display_value || c.Payer_Name || "-");

    const lines = getGroupedByItemLines(c);

    // Payment Turnaround Days: calculated from Claim Lodgement Date -> Payment Date
    const turnaroundDays = calcPaymentTurnaroundDays(c);
    const turnaroundDisplay = formatTurnaroundDays(turnaroundDays);

    const rowCount = Math.max(lines.length, 1);
    const groupClass = groupIdx % 2 === 0 ? "grp-a" : "grp-b";

    const claimCellsHtml = `
      <td rowspan="${rowCount}" class="claim-cell text-center">${claimId}</td>
      <td rowspan="${rowCount}" class="claim-cell">${doctor}</td>
      <td rowspan="${rowCount}" class="claim-cell">${hospital}</td>
      <td rowspan="${rowCount}" class="claim-cell">${patient}</td>
      <td rowspan="${rowCount}" class="claim-cell">${payer}</td>
      <td rowspan="${rowCount}" class="claim-cell text-center">${claimDate}</td>
    `;

    if (!lines.length) {
      html += `
        <tr class="${groupClass} group-first">
          ${claimCellsHtml}
          <td class="no-lines text-center" colspan="3">No line items</td>
          <td class="item-ppdays text-center">${turnaroundDisplay}</td>
        </tr>
      `;
      return;
    }

    // Precompute item-number group spans for rowspan on Item No
    let i = 0;
    const itemSpans = new Array(lines.length).fill(null);
    while (i < lines.length) {
      const currentItem = getLineItemNumber(lines[i]);
      let span = 1;
      while (i + span < lines.length && getLineItemNumber(lines[i + span]) === currentItem) span++;
      itemSpans[i] = span;
      i += span;
    }

    lines.forEach((l, idx) => {
      const itemNo  = getLineItemNumber(l);
      const dos     = getLineDateOfService(l);
      const payDate = getLinePaymentDate(l);
      const span    = itemSpans[idx];

      const itemNoCell = span
        ? `<td rowspan="${span}" class="item-no text-center">${itemNo}</td>`
        : "";

      // Payment Turnaround (Days) carries rowspan over the whole claim
      const turnaroundCell = idx === 0
        ? `<td rowspan="${rowCount}" class="item-ppdays text-center">${turnaroundDisplay}</td>`
        : "";

      html += `
        <tr class="${groupClass} ${idx === 0 ? "group-first" : ""}">
          ${idx === 0 ? claimCellsHtml : ""}
          ${itemNoCell}
          <td class="item-dos text-center">${dos}</td>
          <td class="item-paydate text-center">${payDate}</td>
          ${turnaroundCell}
        </tr>
      `;
    });
  });

  tbody.innerHTML = html;
  tbody.classList.add("fade-in");
  renderSummary(data);
  updateAvgTurnaroundBar(data);

  // Reset horizontal scroll position so the table is never scrolled out of view
  const scrollEl = document.querySelector(".table-scroll");
  if (scrollEl) scrollEl.scrollLeft = 0;
}
/* ---- Average Payment Turnaround Days Bar ---- */
function updateAvgTurnaroundBar(data) {
  const bar = document.getElementById("avg-turnaround-bar");
  const valEl = document.getElementById("avg-turnaround-value");
  if (!bar || !valEl) return;

  const validDays = data
    .map(c => calcPaymentTurnaroundDays(c))
    .filter(v => v !== null && !isNaN(v));

  if (!validDays.length) {
    bar.style.display = "none";
    return;
  }

  const avg = Math.round(validDays.reduce((a, b) => a + b, 0) / validDays.length);
  valEl.textContent = avg === 1 ? "1 Day" : `${avg} Days`;
  bar.style.display = "";
}

/* ---- Sorting by Payment Turnaround (Days) ---- */
function toggleTurnaroundSort() {
  if (TURNAROUND_SORT_DIR === null || TURNAROUND_SORT_DIR === "asc") {
    TURNAROUND_SORT_DIR = "desc";
  } else {
    TURNAROUND_SORT_DIR = "asc";
  }

  const icon = document.getElementById("sort-icon-turnaround");
  if (icon) {
    icon.innerHTML = TURNAROUND_SORT_DIR === "desc" ? "&#8595;" : "&#8593;";
  }

  renderTable(FILTERED_DATA);
}

// Sums Amount_Charged for each item number within ONE claim (mirrors getClaimItemCounts)
function getClaimItemAmounts(c) {
  const amounts = {};
  getClaimLines(c).forEach(l => {
    const num = getLineItemNumber(l);
    const amt = Number(getLineAmount(l)) || 0;
    amounts[num] = (amounts[num] || 0) + amt;
  });
  return amounts;
}
/* ---- Claim_Lines subform helpers ---- */
// "Claim_Lines" is the subform link name on the Claim report.
// Adjust the fallback field names below if your subform's API
// field names differ.

/* ===================================================
   GRAND SUMMARY
   =================================================== */

function computeSummary(claims) {
  const totalClaims = claims.length;
  let totalLineItems = 0;
  let totalBilledAmount = 0; // â¬…ï¸ ADDED
  const typeTotals = {};

  claims.forEach(c => {
    const lines = getEffectiveClaimLines(c);
    totalLineItems += lines.length;
    lines.forEach(l => {
      const type = getLineItemType(l) || "-";
      typeTotals[type] = (typeTotals[type] || 0) + 1;
      totalBilledAmount += Number(getLineAmount(l)) || 0; // â¬…ï¸ ADDED
    });
  });

  return { totalClaims, totalLineItems, typeTotals, totalBilledAmount }; // â¬…ï¸ ADDED totalBilledAmount
}


function fmtMoney(n) {
  return "$ " + (Number(n) || 0).toLocaleString("en-AU", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function renderSummary(data) {
  const el = document.getElementById("report-summary");
  if (!el) return;

  const s = computeSummary(data);

  const typeCards = Object.entries(s.typeTotals)
    .sort((a, b) => b[1] - a[1])
    .map(([type, count]) => `
      <div class="summary-stat">
        <div class="label">${type}</div>
        <div class="value">${count}</div>
      </div>
    `).join("");

  el.innerHTML = `
    <div class="summary-title">Grand Summary</div>
    <div class="summary-grid">
      <div class="summary-stat">
        <div class="label">Total Claims</div>
        <div class="value">${s.totalClaims}</div>
      </div>
      <div class="summary-stat">
        <div class="label">Total Line Items</div>
        <div class="value">${s.totalLineItems}</div>
      </div>
      <div class="summary-stat"> <!-- â¬…ï¸ ADDED -->
        <div class="label">Total Billed Amount</div>
        <div class="value">${fmtMoney(s.totalBilledAmount)}</div>
      </div>
      ${typeCards}
    </div>
  `;
}
function getClaimLines(c) {
  const lines = c.Claim_Lines;
//   const claimCounts = getClaimItemCounts(c);
  return Array.isArray(lines) ? lines : [];
}

// One row per unique item number in a claim, in first-seen order,
// respecting the Item Number filter if one is active.
function getGroupedClaimLines(c) {
  const lines = getClaimLines(c);
  const seen = new Set();
  const grouped = [];

  lines.forEach(l => {
    const num = getLineItemNumber(l);
    if (seen.has(num)) return;
    seen.add(num);
    grouped.push(l);
  });

  if (!SELECTED_ITEM_NUMBERS.length) return grouped;

  const selected = SELECTED_ITEM_NUMBERS.map(v => String(v).trim());
  return grouped.filter(l => selected.includes(String(getLineItemNumber(l)).trim()));
}

function getClaimDate(c) {
  // Filter claims based on Claim Date
  if (c.Claim_Date) {
    return parseZohoDate(c.Claim_Date);
  }
  const lines = getClaimLines(c);
  if (lines.length && lines[0].Date_of_Service) {
    return parseZohoDate(lines[0].Date_of_Service);
  }
  return parseZohoDate(c.Date_of_Service || c.Lodged_Date);
}
function getLineItemNumber(l) {
  if (l.Item && typeof l.Item === "object") {
    return l.Item.zc_display_value || l.Item.ID || "-";
  }
  return l.Item_Number || l.Item || "-";
}



function getLineItemType(l) {
  const ref = getLineItemRef(l);

  // 1) match by lookup record ID (most reliable)
  if (ref && ref.ID && ITEM_TYPE_MAP["id:" + ref.ID]) {
    return ITEM_TYPE_MAP["id:" + ref.ID];
  }
  // 2) match by item number text
  const key = "num:" + normItemKey(getLineItemNumber(l));
  return ITEM_TYPE_MAP[key] || "-";
}

function getLineItemDescription(l) {
  const ref = getLineItemRef(l);

  if (ref && ref.ID && ITEM_DESC_MAP["id:" + ref.ID]) {
    return ITEM_DESC_MAP["id:" + ref.ID];
  }
  const key = "num:" + normItemKey(getLineItemNumber(l));
  return ITEM_DESC_MAP[key] || "-";
}
// Counts how many times each item number appears across the given claims
function computeItemUsageCounts(claims) {
  const counts = {};
  claims.forEach(c => {
    getClaimLines(c).forEach(l => {
      const num = getLineItemNumber(l);
      counts[num] = (counts[num] || 0) + 1;
    });
  });
  return counts;
}

// Counts how many times each item number appears inside ONE claim
function getClaimItemCounts(c) {
  const counts = {};
  getClaimLines(c).forEach(l => {
    const num = getLineItemNumber(l);
    counts[num] = (counts[num] || 0) + 1;
  });
  return counts;
}

// One line per unique item number within a claim
// (usage count is shown in the "Usage Count" column, e.g. "132 - 3")
function getClaimUniqueLines(c) {
  const seen = new Set();
  return getClaimLines(c).filter(l => {
    const num = getLineItemNumber(l);
    if (seen.has(num)) return false;
    seen.add(num);
    return true;
  });
}

// "123 - 3"
function formatUsage(itemNo, counts) {
  return `${itemNo} - ${counts[itemNo] || 0}`;
}

function getLineAmount(l) {
  const amt = l.Amount_Charged;
  return (amt !== undefined && amt !== null && amt !== "") ? amt : null;
}

function getLineStatus(l) {
  return l.Status || "-";
}

function getLineUsageCount(l) {
  const val = l.Usage_Count ?? l.UsageCount ?? l.Count ?? l.Quantity ?? l.Qty;
  return (val !== undefined && val !== null && val !== "") ? val : "-";
}

function buildLineItemsTable(lines) {
  if (!lines.length) {
    return `<div class="line-items-empty">No line items for this claim.</div>`;
  }

  const rows = lines.map(l => {
    const itemNo = getLineItemNumber(l);
    const amt    = getLineAmount(l);
    const status = getLineStatus(l);
    const statusClass = "status-" + String(status).toLowerCase().replace(/\s+/g, "-");

    return `
      <tr>
        <td>${itemNo}</td>
        <td class="line-amount">${amt !== null ? "$ " + amt : "-"}</td>
        <td><span class="status-badge ${statusClass}">${status}</span></td>
      </tr>
    `;
  }).join("");

  return `
    <div class="line-items-wrap">
      <div class="line-items-title">Claim Line Items (${lines.length})</div>
      <table class="line-items-table">
        <thead>
          <tr>
            <th>Item Number</th>
            <th class="line-amount">Amount</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

function toggleLineItems(rowId, btn) {
  const row = document.getElementById(rowId);
  if (!row) return;
  const isOpen = row.style.display !== "none";
  row.style.display = isOpen ? "none" : "table-row";
  btn.classList.toggle("open", !isOpen);
  const arrow = btn.querySelector(".toggle-arrow");
  if (arrow) arrow.innerHTML = isOpen ? "&#9656;" : "&#9662;";
}
/* ===================================================
   DRILL-DOWN MODAL
   =================================================== */

function drillDown(claimId) {
  const claim = ALL_CLAIMS.find(c => String(c.ID) === String(claimId));
  if (!claim) return;

  // Build a detail table from all non-empty fields
  const skip = new Set(["added_user", "added_time", "modified_time", "Claim_Lines"]);
  const rows = Object.entries(claim)
    .filter(([k, v]) => !skip.has(k) && v !== null && v !== undefined && v !== "")
    .map(([k, v]) => {
      const label = k.replace(/_/g, " ");
      let val = v;
      if (typeof v === "object") val = v.zc_display_value || JSON.stringify(v);
      return `<tr><th>${label}</th><td>${val}</td></tr>`;
    })
    .join("");

  // Inject or re-use modal
  let modal = document.getElementById("drill-modal");
  if (!modal) {
    modal = document.createElement("div");
    modal.id = "drill-modal";
    modal.innerHTML = `
      <div class="modal-overlay" onclick="closeModal()"></div>
      <div class="modal-box">
        <div class="modal-header">
          <span class="modal-title">Claim Details</span>
          <button class="modal-close" onclick="closeModal()">&#x2715;</button>
        </div>
        <div class="modal-body"><table id="drill-table"></table></div>
      </div>
    `;
    document.body.appendChild(modal);
  }

  document.getElementById("drill-table").innerHTML = rows;
  modal.classList.add("open");
}

function closeModal() {
  const modal = document.getElementById("drill-modal");
  if (modal) modal.classList.remove("open");
}

function getExportRows() {
  const rows = [];

  FILTERED_DATA.forEach(c => {
    const claimId   = c.Claim_ID || c.ID || "-";
    const claimDate = formatClaimDate(c);
    const doctor    = c.Doctor?.zc_display_value   || c.Doctor_Name   || "-";
    const hospital  = c.Hospital?.zc_display_value || c.Hospital_Name || "-";
    const patient   = getPatientDisplayWithDOB(c);
    const turnaroundDisplay = formatTurnaroundDays(calcPaymentTurnaroundDays(c));

    const payerObj  = getClaimPayer(c);
    const payer     = payerObj ? payerObj.label : (c.Payer?.zc_display_value || c.Payer_Name || "-");
    const baseRow   = {
      "Claim ID": claimId, "Doctor": doctor, "Hospital": hospital,
      "Patient": patient, "Payer": payer, "Claim Date": claimDate
    };

    const lines = getGroupedByItemLines(c);

    if (!lines.length) {
      rows.push({
        ...baseRow,
        "Item No": "-", "Date of Service": "-",
        "Payment Date": "-", "Payment Turnaround (Days)": turnaroundDisplay
      });
      return;
    }

    let i = 0;
    const itemSpans = new Array(lines.length).fill(null);
    while (i < lines.length) {
      const currentItem = getLineItemNumber(lines[i]);
      let span = 1;
      while (i + span < lines.length && getLineItemNumber(lines[i + span]) === currentItem) span++;
      itemSpans[i] = span;
      i += span;
    }

    lines.forEach((l, idx) => {
      const itemNo = getLineItemNumber(l);
      const isFirstOfGroup = itemSpans[idx] !== null;

      rows.push({
        ...baseRow,
        "Item No":                   isFirstOfGroup ? itemNo : "",
        "Date of Service":           getLineDateOfService(l),
        "Payment Date":              getLinePaymentDate(l),
        "Payment Turnaround (Days)": idx === 0 ? turnaroundDisplay : ""
      });
    });
  });

  return rows;
}

/* ---------------- EXPORT EXCEL ---------------- */

/* ===================================================
   EXPORT EXCEL â€” styled to match the Claims Status Report
   design (title, filter summary row, colored table header).

   SETUP â€” add this ONCE in your HTML, before your other scripts:

   <script src="https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js"></script>

   This gives you the global `XLSX` object used below. Unlike the
   plain "xlsx" CDN build (which silently ignores cell styling),
   this build actually renders fill color, font color, alignment,
   and borders in the downloaded file â€” that's why the header
   color/alignment wasn't showing up before.
   =================================================== */

/* ===================================================
   BRAND COLORS (hex, no '#', used by xlsx-js-style)
   =================================================== */
const XLSX_BRAND = {
  navy: "1E2D5A",
  navyText: "2D374F",
  green: "1F7A5C",
  white: "FFFFFF",
  lightGrey: "E5E7EB",
  rowAlt: "F6F7F9"
};

/* ===================================================
   EXPORT TO EXCEL
   =================================================== */
function exportExcel() {
  const rows = getExportRows();
  if (!rows.length) { alert("No data to export."); return; }

  const info = getActiveFilterInfo();
  const aoa = [];

  aoa.push(["Claims Turnaround Time Report"]);
  aoa.push([`Doctor: ${info.doctor || "All"}`]);
  aoa.push([`Hospital: ${info.hospital || "All"}`]);
  aoa.push([`Date Range: ${formatDateRange(info.dateFrom, info.dateTo)}`]);
  aoa.push([`Generated On: ${new Date().toLocaleString("en-AU", {
    timeZone: "Australia/Sydney",
    day: "2-digit", month: "short", year: "numeric",
    hour: "numeric", minute: "2-digit", hour12: true
  })}`]);
  aoa.push([]);

  const HEADER_ROW = aoa.length;
  aoa.push([
    "Claim ID", "Doctor", "Hospital", "Patient", "Payer", "Claim Date",
    "Item No", "Date of Service", "Payment Date", "Payment Turnaround (Days)"
  ]);


  const DATA_START_ROW = aoa.length;
  const groupBoundaryRows = [];

FILTERED_DATA.forEach(c => {
  const claimId  = c.Claim_ID || c.ID || "-";
  const claimDate = formatClaimDate(c);
  const doctor   = c.Doctor?.zc_display_value   || c.Doctor_Name   || "-";
  const hospital = c.Hospital?.zc_display_value || c.Hospital_Name || "-";
  const patient  = (getClaimPatientInfo(c) || {}).label || "-";

  const lines = getGroupedByItemLines(c);
  groupBoundaryRows.push(aoa.length);

  if (!lines.length) {
    aoa.push([claimId, doctor, hospital, patient, claimDate, "-", "-", "-", "-"]);
    return;
  }

  let i = 0;
  const itemSpans = new Array(lines.length).fill(null);
  while (i < lines.length) {
    const currentItem = getLineItemNumber(lines[i]);
    let span = 1;
    while (i + span < lines.length && getLineItemNumber(lines[i + span]) === currentItem) span++;
    itemSpans[i] = span;
    i += span;
  }

  lines.forEach((l, idx) => {
    const itemNo = getLineItemNumber(l);
    const isFirstOfGroup = itemSpans[idx] !== null;

    aoa.push([
      idx === 0 ? claimId   : "",
      idx === 0 ? doctor    : "",
      idx === 0 ? hospital  : "",
      idx === 0 ? patient   : "",
      idx === 0 ? claimDate : "",
      isFirstOfGroup ? itemNo : "",
      getLineDateOfService(l),
      getLinePaymentDate(l),
      calcProcessPaymentDays(l)
    ]);
  });
});
  const DATA_END_ROW = aoa.length - 1;

  /* ---------------- BUILD WORKSHEET ---------------- */

  const worksheet = XLSX.utils.aoa_to_sheet(aoa);
  worksheet["!merges"] = [{ s: { r: 0, c: 0 }, e: { r: 0, c: 8 } }]; // 9 columns (0-8)
  worksheet["!cols"] = [
    { wch: 14 }, { wch: 18 }, { wch: 20 }, { wch: 20 }, { wch: 14 }, // Claim ID, Doctor, Hospital, Patient, Claim Date
    { wch: 12 }, { wch: 14 }, { wch: 14 }, { wch: 20 }                // Item No, DoS, Pay Date, Process Payment Days
  ];

  function setStyle(row, col, style) {
    const cellRef = XLSX.utils.encode_cell({ r: row, c: col });
    if (!worksheet[cellRef]) worksheet[cellRef] = { v: "" };
    worksheet[cellRef].s = style;
  }

  const headerStyle = {
    font: { bold: true, sz: 10, color: { rgb: XLSX_BRAND.white } },
    fill: { fgColor: { rgb: XLSX_BRAND.green } },
    alignment: { horizontal: "center", vertical: "center" },
    border: {
      top: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      bottom: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      left: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      right: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } }
    }
  };
  const dataCellStyle = {
    font: { sz: 9, color: { rgb: XLSX_BRAND.navyText } },
    border: {
      top: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      bottom: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      left: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } },
      right: { style: "thin", color: { rgb: XLSX_BRAND.lightGrey } }
    }
  };
  const countCellStyle = { ...dataCellStyle, alignment: { horizontal: "right" }, numFmt: "#,##0" };
  const altRowFill = { fgColor: { rgb: XLSX_BRAND.rowAlt } };

  setStyle(0, 0, { font: { bold: true, sz: 14, color: { rgb: XLSX_BRAND.navy } }, alignment: { horizontal: "center" } });
  for (let r = 1; r <= 4; r++) setStyle(r, 0, { font: { sz: 9, italic: true, color: { rgb: XLSX_BRAND.navyText } } });

  for (let c = 0; c <= 9; c++) setStyle(HEADER_ROW, c, headerStyle); // 10 columns (0-9)

  for (let r = DATA_START_ROW; r <= DATA_END_ROW; r++) {
    const isAlt = (r - DATA_START_ROW) % 2 === 1;
    const isGroupStart = groupBoundaryRows.includes(r);
    for (let c = 0; c <= 9; c++) { // 10 columns (0-9)
      let style = isAlt ? { ...dataCellStyle, fill: altRowFill } : dataCellStyle;
      if (c === 0 || c === 5 || c === 6 || c === 7 || c === 8 || c === 9) style = { ...style, alignment: { horizontal: "center" } };
      if (isGroupStart) {
        style = { ...style, border: { ...style.border, top: { style: "medium", color: { rgb: XLSX_BRAND.navy } } } };
      }
      setStyle(r, c, style);
    }
  }

  /* ---------------- SAVE ---------------- */

  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Claims Report");
  XLSX.writeFile(workbook, "Claims Turnaround Time Report.xlsx");
}
/**
 * Billing Status Report â€” styled to match the Medi Elves report template.
 */

const BRAND = {
  navy: [30, 45, 90],
  navyText: [45, 55, 80],
  grey: [110, 118, 130],
  lightGrey: [235, 237, 240],
  rowAlt: [246, 247, 249],
  white: [255, 255, 255],
  green: [31, 122, 92]
};

const ICON_COLOR = [30, 130, 76];

function getActiveFilters() {
  const val = (id) => {
    const el = document.getElementById(id);
    return el && el.value ? el.value.trim() : "";
  };
  return {
    hospital: val("filterHospital"),
    doctor: val("filterDoctor"),
    dateFrom: val("filterDateFrom"),
    dateTo: val("filterDateTo")
  };
}

function applyFilters(rows, filters) {
  return rows.filter((r) => {
    if (filters.hospital && r["Hospital"] !== filters.hospital) return false;
    if (filters.doctor && r["Doctor"] !== filters.doctor) return false;

    if (filters.dateFrom || filters.dateTo) {
      const rowDate = r["Date"];
      if (filters.dateFrom && rowDate < filters.dateFrom) return false;
      if (filters.dateTo && rowDate > filters.dateTo) return false;
    }
    return true;
  });
}

function getFilterDisplayLabel(id, fallback) {
  const wrapper = document.getElementById(id);
  if (!wrapper) return fallback;
  const valueSpan = wrapper.querySelector(".ss-value");
  const text = valueSpan ? valueSpan.textContent.trim() : "";
  return (text && text !== fallback) ? text : fallback;
}

function getActiveFilterInfo() {
  return {
    doctor:   CURRENT_DOCTOR_NAME || "All Doctors",
    hospital: getFilterDisplayLabel("f-location", "All Hospitals"),
    patient:  getFilterDisplayLabel("f-patient",  "All Patients"),
    dateFrom: (document.getElementById("f-from") || {}).value || "",
    dateTo:   (document.getElementById("f-to")   || {}).value || ""
  };
}



function formatDateRange(from, to) {
  const pretty = (val) => {
    const d = parseZohoDate(val);
    return (d && !isNaN(d.getTime()))
      ? d.toLocaleDateString("en-AU", { day: "2-digit", month: "short", year: "numeric", timeZone: "Australia/Sydney" })
      : val;
  };
  if (from && to) return `${pretty(from)} - ${pretty(to)}`;
  if (from) return `From ${pretty(from)}`;
  if (to) return `Up to ${pretty(to)}`;
  return "All Dates";
}

function buildPdfBody() {
  const body = [];
  PDF_GROUP_STARTS = [];

  FILTERED_DATA.forEach(c => {
    const claimId   = c.Claim_ID || c.ID || "-";
    const claimDate = formatClaimDate(c);
    const doctor    = c.Doctor?.zc_display_value   || c.Doctor_Name   || "-";
    const hospital  = c.Hospital?.zc_display_value || c.Hospital_Name || "-";
    const patient   = (getClaimPatientInfo(c) || {}).label || "-";
    const payerObj  = getClaimPayer(c);
    const payer     = payerObj ? payerObj.label : (c.Payer?.zc_display_value || c.Payer_Name || "-");

    const lines = getGroupedByItemLines(c);
    PDF_GROUP_STARTS.push(body.length);

    const turnaroundDisplay = formatTurnaroundDays(calcPaymentTurnaroundDays(c));

    if (!lines.length) {
      body.push([claimId, doctor, hospital, patient, payer, claimDate, "-", "-", "-", turnaroundDisplay]);
      return;
    }

    let i = 0;
    const itemSpans = new Array(lines.length).fill(null);
    while (i < lines.length) {
      const currentItem = getLineItemNumber(lines[i]);
      let span = 1;
      while (i + span < lines.length && getLineItemNumber(lines[i + span]) === currentItem) span++;
      itemSpans[i] = span;
      i += span;
    }

    lines.forEach((l, idx) => {
      const itemNo = getLineItemNumber(l);
      const span = itemSpans[idx];

      const row = [
        idx === 0 ? claimId   : "",
        idx === 0 ? doctor    : "",
        idx === 0 ? hospital  : "",
        idx === 0 ? patient   : "",
        idx === 0 ? payer     : "",
        idx === 0 ? claimDate : ""
      ];

      if (span) {
        row.push({ content: itemNo, rowSpan: span });
      }

      row.push(getLineDateOfService(l));
      row.push(getLinePaymentDate(l));
      row.push(idx === 0 ? turnaroundDisplay : "");

      body.push(row);
    });
  });

  return body;
}
