async function exportPDF() {
  if (!FILTERED_DATA.length) { alert("No data to export."); return; }

  await loadLogoAsDataURL();

  const info = getActiveFilterInfo();
  const { jsPDF } = window.jspdf;

  const doc = new jsPDF({
    orientation: "l",   // â¬…ï¸ CHANGED â€” landscape
    unit: "pt",
    format: "a4"
  });

  const pageW = doc.internal.pageSize.getWidth();   // â¬…ï¸ now ~841.89pt
  const pageH = doc.internal.pageSize.getHeight();  // â¬…ï¸ now ~595.28pt
  const margin = 40;

  const headerInfo = {
    hospital: info.hospital,
    doctor: info.doctor,
    date: formatDateRange(info.dateFrom, info.dateTo),
    generatedOn: new Date().toLocaleString("en-AU", {
      timeZone: "Australia/Sydney",
      day: "2-digit", month: "short", year: "numeric",
      hour: "numeric", minute: "2-digit", hour12: true
    })
  };

  const HEADER_HEIGHT = 168;
  const FOOTER_RESERVED = 110;

  /* ---------------- MAIN CLAIMS TABLE ---------------- */
  doc.autoTable({
    startY: HEADER_HEIGHT,
    margin: { top: HEADER_HEIGHT, left: margin, right: margin, bottom: FOOTER_RESERVED },
    theme: "grid",
    head: [[
      "Claim ID", "Doctor", "Hospital", "Patient", "Payer", "Claim Date",
      "Item No", "Date of Service", "Payment Date", "Payment Turnaround (Days)"
    ]],
    body: buildPdfBody(),

    didParseCell: function (data) {
      if (data.section !== "body") return;

      let lines = (data.cell.text || []).map(stripDob);

      if (lines.length > 1 && isDateOnly(lines[lines.length - 1])) {
        lines = lines.slice(0, -1);
      }

      data.cell.text = lines;

      if (PDF_GROUP_STARTS.includes(data.row.index)) {
        data.cell.styles.lineWidth = { top: 0.5, bottom: 0.5, left: 0.5, right: 0.5 };
      }
    },
    styles: {
      fontSize: 7.5,
      textColor: [0, 0, 0],
      fillColor: BRAND.white,
      lineColor: BRAND.lightGrey,
      lineWidth: 0.5,
      cellPadding: 4,
      overflow: "linebreak",
      valign: "middle"
    },
    headStyles: {
      fillColor: BRAND.navy,
      textColor: BRAND.white,
      fontStyle: "bold",
      fontSize: 7,
      cellPadding: 5,
      valign: "middle"
    },
    tableWidth: pageW - margin * 2,
    columnStyles: {
      0: { cellWidth: 50, halign: "center" },   // Claim ID
      1: { cellWidth: 78, halign: "left" },     // Doctor
      2: { cellWidth: 92, halign: "left" },     // Hospital
      3: { cellWidth: 85, halign: "left" },     // Patient
      4: { cellWidth: 75, halign: "left" },     // Payer
      5: { cellWidth: 62, halign: "center" },   // Claim Date
      6: { cellWidth: 42, halign: "center" },   // Item No
      7: { cellWidth: 68, halign: "center" },   // Date of Service
      8: { cellWidth: 68, halign: "center" },   // Payment Date
      9: { cellWidth: 72, halign: "center" }    // Payment Turnaround (Days)
    },
    didDrawPage: () => {
      drawHeader(doc, pageW, margin, headerInfo);
      drawFooter(doc, pageW, margin);
    }
  });


  /* ---------------- SAVE ---------------- */
  doc.save("Claims Turnaround Time Report.pdf");
}

function drawGrandSummary(doc, pageW, pageH, margin, headerInfo, HEADER_HEIGHT, FOOTER_RESERVED) {
  const s = computeSummary(FILTERED_DATA);

  const rows = [
    ["Total Claims", String(s.totalClaims)],
    ["Total Line Items", String(s.totalLineItems)],
    ["Total Billed Amount", fmtMoney(s.totalBilledAmount)] // â¬…ï¸ ADDED
  ];
  Object.entries(s.typeTotals)
    .sort((a, b) => b[1] - a[1])
    .forEach(([type, count]) => rows.push([`Total ${type}`, String(count)]));


  const lastY = doc.lastAutoTable ? doc.lastAutoTable.finalY : HEADER_HEIGHT;
  const titleGap = 24;
  const neededHeight = titleGap + 24 + rows.length * 18 + 20; // rough estimate for fit-check

  // If there isn't enough room before the footer, start a new page
  let startY = lastY + titleGap;
  if (startY + neededHeight > pageH - FOOTER_RESERVED) {
    doc.addPage();
    drawHeader(doc, pageW, margin, headerInfo);
    drawFooter(doc, pageW, margin);
    startY = HEADER_HEIGHT + titleGap;
  }

  doc.autoTable({
    startY: startY,
    margin: { left: margin, right: margin, bottom: FOOTER_RESERVED },
    theme: "grid",
    head: [["GRAND SUMMARY", ""]],
    body: rows,
    tableWidth: 260,
    styles: {
      fontSize: 8.5,
      textColor: [0, 0, 0],
      lineColor: BRAND.lightGrey,
      lineWidth: 0.5,
      cellPadding: 5,
      valign: "middle"
    },
    headStyles: {
      fillColor: BRAND.navy,
      textColor: BRAND.white,
      fontStyle: "bold",
      fontSize: 9,
      halign: "left"
    },
    columnStyles: {
      0: { cellWidth: 170, fontStyle: "bold", textColor: BRAND.navyText },
      1: { cellWidth: 90, halign: "right", fontStyle: "bold", textColor: BRAND.navy }
    },
    didParseCell: function (data) {
      if (data.section === "head" && data.column.index === 1) {
        data.cell.text = [""]; // keep second header cell blank
      }
    },
    didDrawPage: () => {
      drawHeader(doc, pageW, margin, headerInfo);
      drawFooter(doc, pageW, margin);
    }
  });
}
function drawHeader(doc, pageW, margin, info) {
  const logoW = 150, logoH = 55.5;
  if (LOGO_DATA_URL) {
    doc.addImage(LOGO_DATA_URL, "PNG", margin, 24, logoW, logoH);
  }

  doc.setFont("helvetica", "bold");
  doc.setFontSize(17);
  doc.setTextColor(...BRAND.navy);
  doc.text("Claims Turnaround Time Report", pageW - margin, 52, { align: "right" });

  const sepY = 96;
  doc.setFillColor(...ICON_COLOR);
  doc.circle(margin + 3, sepY, 2.2, "F");
  doc.setDrawColor(...BRAND.lightGrey);
  doc.setLineWidth(1);
  doc.line(margin + 12, sepY, pageW - margin, sepY);

  const items = [
    { icon: "person",   label: "DOCTOR",        value: info.doctor },
    { icon: "hospital", label: "HOSPITAL",      value: info.hospital },
    { icon: "calendar", label: "REPORT PERIOD", value: info.date },
    { icon: "clock",    label: "GENERATED ON",  value: info.generatedOn }
  ];

  const labelY   = sepY + 30;
  const iconSize = 15;
  const textGap  = 8;
  const colGap   = 14;
  const colW     = (pageW - margin * 2) / items.length;
  const valueLineHeight = 11;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  const wrapped = items.map((item, i) => {
    const textX = margin + colW * i + iconSize + textGap;
    const availableWidth = colW - iconSize - textGap - colGap;
    const lines = doc.splitTextToSize(String(item.value), Math.max(availableWidth, 40)).slice(0, 2);
    return { ...item, textX, lines };
  });

  wrapped.forEach((item) => {
    const valueBlockHeight = item.lines.length * valueLineHeight;
    const iconCenterY = labelY - 4 + valueBlockHeight / 2 - (valueLineHeight / 2);
    const iconX = item.textX - textGap - iconSize / 2;

    drawIcon(doc, item.icon, iconX, iconCenterY, ICON_COLOR);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(7);
    doc.setTextColor(...BRAND.grey);
    doc.text(item.label, item.textX, labelY);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(...BRAND.navyText);
    item.lines.forEach((line, li) => {
      doc.text(line, item.textX, labelY + 14 + li * valueLineHeight);
    });
  });
}

function drawFooter(doc, pageW, margin) {
  const pageH = doc.internal.pageSize.getHeight();
  const lineY = pageH - 100;

  doc.setDrawColor(...BRAND.lightGrey);
  doc.setLineWidth(1);
  doc.line(margin, lineY, pageW - margin, lineY);

  const textX  = margin + 18;
  const titleY = lineY + 16;

  drawIcon(doc, "lock", margin + 6, titleY - 4, ICON_COLOR);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(8);
  doc.setTextColor(...BRAND.navyText);
  doc.text("CONFIDENTIAL - CONTAINS SENSITIVE HEALTH INFORMATION", textX, titleY);

  const pageCount = doc.internal.getNumberOfPages();
  const current    = doc.internal.getCurrentPageInfo().pageNumber;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(...BRAND.grey);
  doc.text(`Page ${current} of ${pageCount}`, pageW - margin, titleY, { align: "right" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(7);
  doc.setTextColor(...BRAND.grey);
  const notice =
    "This document contains confidential patient and claims information and is intended only for the named recipient and authorised " +
    "personnel. Unauthorised access, use, copying, forwarding or disclosure is prohibited. If you received this document in error, please " +
    "notify Medi Elves immediately, delete all electronic copies and securely destroy any printed copies.";
  const noticeLines = doc.splitTextToSize(notice, pageW - margin - textX);
  doc.text(noticeLines, textX, titleY + 12);

  const contactY    = titleY + 12 + noticeLines.length * 9 + 14;
  const contactColW = (pageW - margin * 2) / 3;

  drawIcon(doc, "phone", margin + 6, contactY, ICON_COLOR);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...BRAND.navyText);
  doc.text("1800 956 692", margin + 18, contactY + 3);

  const emailX = margin + contactColW;
  drawIcon(doc, "mail", emailX + 6, contactY, ICON_COLOR);
  doc.text("admin@medielves.com.au", emailX + 18, contactY + 3);

  const webX = margin + contactColW * 2;
  drawIcon(doc, "globe", webX + 6, contactY, ICON_COLOR);
  doc.text("www.medielves.com.au", webX + 18, contactY + 3);
}

function drawIcon(doc, type, cx, cy, color) {
  doc.setDrawColor(...color);
  doc.setFillColor(...color);
  doc.setLineWidth(1);

  switch (type) {
    case "person":
      doc.circle(cx, cy - 4, 3, "S");
      doc.ellipse(cx, cy + 3, 5, 4, "S");
      break;
    case "hospital":
      doc.rect(cx - 5, cy - 5, 10, 10, "S");
      doc.line(cx, cy - 3, cx, cy + 3);
      doc.line(cx - 3, cy, cx + 3, cy);
      break;
    case "calendar":
      doc.roundedRect(cx - 6, cy - 5, 12, 10, 1.5, 1.5, "S");
      doc.line(cx - 6, cy - 2, cx + 6, cy - 2);
      doc.line(cx - 3, cy - 6.5, cx - 3, cy - 4);
      doc.line(cx + 3, cy - 6.5, cx + 3, cy - 4);
      break;
    case "clock":
      doc.circle(cx, cy, 6, "S");
      doc.line(cx, cy, cx, cy - 3.5);
      doc.line(cx, cy, cx + 3, cy);
      break;
    case "lock":
      doc.roundedRect(cx - 5, cy - 2, 10, 8, 1.5, 1.5, "S");
      doc.circle(cx, cy - 4, 3.5, "S");
      break;
    case "phone":
      doc.roundedRect(cx - 3, cy - 6, 6, 12, 1.5, 1.5, "S");
      break;
    case "mail":
      doc.rect(cx - 6, cy - 4, 12, 8, "S");
      doc.line(cx - 6, cy - 4, cx, cy);
      doc.line(cx + 6, cy - 4, cx, cy);
      break;
    case "globe":
      doc.circle(cx, cy, 6, "S");
      doc.ellipse(cx, cy, 3, 6, "S");
      doc.line(cx - 6, cy, cx + 6, cy);
      break;
    default:
      doc.circle(cx, cy, 4, "S");
  }
}

